import 'dart:convert';

/// The Android libraries the release APK ships, with the licence each POM declares:
/// assets/licenses/android-libraries.json, generated by scripts/gen-android-licenses.dart (CI
/// checks that it is not stale). About lists them from it. Plain Dart, so the script can use it.

/// One Android library on the release classpath, with the licence its POM declares.
class AndroidLibrary {
  const AndroidLibrary(this.id, this.version, this.license);

  /// `group:artifact`.
  final String id;
  final String version;

  /// A normalised licence name: `Apache-2.0`, `BSD-3-Clause`, or `A OR B` for a dual licence.
  final String license;
}

String renderLibraries(List<AndroidLibrary> libraries) {
  const header =
      'Generated by scripts/gen-android-licenses.dart from the POMs of the release classpath. '
      'Do not edit.';
  final data = {
    '_': header,
    'libraries': [
      for (final l in libraries) {'id': l.id, 'version': l.version, 'license': l.license},
    ],
  };
  return '${const JsonEncoder.withIndent('  ').convert(data)}\n';
}

List<AndroidLibrary> parseLibraries(String json) {
  final data = jsonDecode(json) as Map<String, dynamic>;
  return [
    for (final l in data['libraries'] as List<dynamic>)
      AndroidLibrary(
        (l as Map<String, dynamic>)['id'] as String,
        l['version'] as String,
        l['license'] as String,
      ),
  ];
}
